def characterReplacement(s: str, k: int) -> int:
    max_len = 0
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            sub = s[i:j+1]
            counts = {}
            max_freq = 0
            for char in sub:
                counts[char] = counts.get(char, 0) + 1
                if counts[char] > max_freq:
                    max_freq = counts[char]
            sub_len = j - i + 1
            if sub_len - max_freq <= k:
                if sub_len > max_len:
                    max_len = sub_len
    return max_len

